/* Manufacturer evidence is separate from view labels and saved project edits. */
const verifiedCatalog={};
const verificationFiles=['verified-light-a.json','verified-light-b.json','verified-control-power.json','verified-video.json','corrections-light-fixtures.json','corrections-effects.json','corrections-controls.json','corrections-video.json'];
async function loadVerification(){const files=await Promise.all(verificationFiles.map(async file=>{const r=await fetch(file,{cache:'no-cache'});if(!r.ok)throw Error('Не загружен справочник '+file);return r.json()}));for(const data of files)for(const [id,value]of Object.entries(data))verifiedCatalog[id]={...(verifiedCatalog[id]||{}),...value};const response=await fetch('catalog-short-names.json',{cache:'no-cache'});if(!response.ok)throw Error('Не загружены названия моделей');Object.assign(modelShortNames,await response.json());applyVerifiedCatalog();}
function applyVerifiedCatalog(){for(const m of catalog){const patch=verifiedCatalog[m.id];if(patch){Object.assign(m,patch);if(Array.isArray(m.notes))m.notes=m.notes.join(' ');if(m.verification&&!m.verification.sources?.length&&m.source)m.verification={...m.verification,sources:[m.source]};if(!m.dmxConnector&&Array.isArray(m.signalPorts)){const values=[...new Set(m.signalPorts.filter(p=>p.type==='dmx').map(p=>p.connector).filter(Boolean))];if(values.length===1)m.dmxConnector=values[0]}if(patch.verification?.sources?.length)m.manual=patch.verification.sources[0]}}}
function finishVerifiedCatalog(){applyVerifiedCatalog();for(const m of catalog)if(['snl-311','snl-503'].includes(m.id))m.catalogHidden=true;for(const [alias,original] of [['ubl12h','snl-499'],['focusflex','snl-444']]){const a=catalog.find(m=>m.id===alias),b=catalog.find(m=>m.id===original);if(a&&b){a.catalogHidden=true;a.aliasOf=original}}for(const m of catalog){if(m.requiresDmxProfile||(m.kind==='console'&&!(m.signalPorts||[]).some(p=>p.type==='dmx'&&p.out)))m.catalogHidden=true;m.catalogTitle=shortModelName(m);m.shortName=shortModelName(m);if(m.category==='power')continue;if(m.generic){m.catalogSubtitle='';continue}const data=verifiedCatalog[m.id],mm=modes(m);if(data?.catalogSubtitle){m.catalogSubtitle=data.catalogSubtitle;continue}const bits=[];
 if(['light','effect'].includes(m.category)){
  if(m.colorSystem)bits.push(m.colorSystem.replace(/\s*\/\s*virtual CMY/i,'/CMY'));
  if(mm.length){const channels=[...new Set(mm.map(v=>v.channels))].sort((a,b)=>a-b);bits.push((channels.length===1?channels[0]:channels[0]+'–'+channels.at(-1))+' CH')}
  if(m.dmxPhysical===false&&m.dmx)bits.push('WiFLY');else if(m.dmxConnector){const pins=[...m.dmxConnector.matchAll(/([35])-pin/g)].map(v=>v[1]);bits.push(pins.length?[...new Set(pins)].join('/')+'-pin':m.dmxConnector)}
  if(!bits.length&&Number.isFinite(m.watts))bits.push(m.watts+' W');
  if(!bits.length)bits.push(m.dmx?'Режим требует сверки':m.catalogSubtitle&&!/^(PAR|Wash|Spot|Beam|Стробоскоп|Лазер|Хейзер|Дым)$/.test(m.catalogSubtitle)?m.catalogSubtitle:'Модель требует уточнения');
  m.catalogSubtitle=bits.slice(0,3).join(' · ');
 }
 }}
function verificationMarkup(m){const v=m.verification;if(!v)return m.generic?'<p class="help">Блок без модели. Выбери конкретный прибор в каталоге, чтобы получить режимы и разъёмы из его документации.</p>':'<p class="help">Документация этой модели ещё не подтверждена.</p>';const labels={verified:'Данные проверены',partial:'Проверено частично',unresolved:'Нужно уточнить модель',generic:'Блок без модели',not_applicable:'Без DMX'};return`<div class="verification-note ${v.status==='verified'?'verified':''}"><strong>${esc(labels[v.status]||v.status)}</strong>${v.note?`<p class="help">${esc(v.note)}</p>`:''}${v.missingFields?.length?`<p class="help">Осталось проверить: ${esc(v.missingFields.map(f=>({modes:'DMX-режимы',connectors:'разъёмы',watts:'потребление',powerLink:'сквозное питание',model:'точная модель',dmxConnector:'DMX-разъём',maxPower:'максимальная мощность',powerConnector:'силовой разъём',signalPorts:'сигнальные порты'})[f]||f).join(', '))}.</p>`:''}</div>${m.connectors?.length?`<p class="help"><strong>Разъёмы:</strong><br>${m.connectors.map(esc).join('<br>')}</p>`:''}${(v.sources||[]).map((url,i)=>`<a class="doc-link" href="${esc(safeUrl(url))}" target="_blank" rel="noopener">Источник ${i+1} · ${esc(new URL(url).hostname.replace(/^www\./,''))} ↗</a>`).join('')}`}
